    ('b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Quiz — Quand une mutation devient une maladie', 'SVT', '1re', 'Mutations, patrimoine génétique et santé', 'ed480054-bb6b-5a88-b3ae-cd6aa94c59b5'::uuid),
    ('e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Quiz — Une cellule qui échappe au contrôle', 'SVT', '1re', 'Origine et mécanismes de la cancérisation', '76f0c45f-acfc-5c49-8d92-0e829c2e56cb'::uuid),
    ('471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Quiz — La sélection naturelle observée en direct', 'SVT', '1re', 'Variation génétique des bactéries et résistance aux antibiotiques', '7ba0b2f8-60e9-51a4-b4cd-f4041570b3ed'::uuid),
    ('2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Quiz — La première ligne de défense', 'SVT', '1re', 'L’immunité innée', 'e311ee7f-4207-5d76-8af1-016214d259fc'::uuid),
    ('fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Quiz — Une réponse spécifique et une mémoire', 'SVT', '1re', 'L’immunité adaptative', '1bf840bd-23c2-5464-8f42-5eb155456daf'::uuid),
    ('fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Quiz — Utiliser le système immunitaire comme traitement', 'SVT', '1re', 'La vaccination et l’immunothérapie', '66241b49-24d8-542e-b050-e04d78cca11b'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
