ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('326e1fe1-b245-5b87-a498-8074d9ad8375'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'Que produit une mitose ?', 'mcq', '["Deux cellules filles génétiquement identiques à la cellule mère","Quatre cellules haploïdes","Deux cellules haploïdes","Une cellule à 4n chromosomes"]'::jsonb, 0, 'La mitose est une division conforme : elle assure la stabilité génétique.', 1),
    ('308772c8-2589-5245-a70d-d9459d304116'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'Pendant quelle phase du cycle l’ADN est-il répliqué ?', 'mcq', '["La phase S de l’interphase","La prophase","L’anaphase","La phase G2"]'::jsonb, 0, 'Chaque chromosome passe alors d’une à deux chromatides.', 2),
    ('bc35b213-6247-5f60-9187-b1d5d06424f8'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'La méiose produit quatre cellules haploïdes à partir d’une cellule diploïde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Deux divisions successives pour une seule réplication de l’ADN.', 3),
    ('beceee16-54b7-50e1-b1e7-dc2b4cbfa4c8'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'Qu’est-ce que le brassage intrachromosomique ?', 'mcq', '["L’échange de segments entre chromatides de chromosomes homologues","La répartition aléatoire des homologues","La séparation des chromatides en anaphase II","La fusion des gamètes"]'::jsonb, 0, 'C’est le crossing-over, qui se produit en prophase I.', 4),
    ('5702a398-b785-5180-b93c-0ef8e9ccd7df'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'À quel moment de la méiose se sépare la paire de chromosomes homologues ?', 'mcq', '["En anaphase I","En anaphase II","En métaphase I","En télophase II"]'::jsonb, 0, 'C’est ce qui rend la première division réductionnelle.', 5),
    ('8cb16625-9830-5f79-8e0a-c4f463660c3e'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'Le brassage interchromosomique résulte de la disposition aléatoire des paires d’homologues en métaphase I.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque paire s’oriente indépendamment des autres : plus de 8 millions de combinaisons chez l’humain.', 6),
    ('08a5fb83-fc40-5306-8ca0-9079181683db'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'Que se passe-t-il pendant l’anaphase d’une mitose ?', 'mcq', '["Les deux chromatides de chaque chromosome se séparent","Les chromosomes homologues se séparent","Les chromosomes se condensent","La cellule se coupe en deux"]'::jsonb, 0, 'Chaque pôle reçoit ainsi un exemplaire complet de l’information.', 7),
    ('2699c530-6f21-562b-bab8-050cb51d5340'::uuid, '77102249-bafb-5167-90b7-6adaa1dba752'::uuid, 'La méiose II ressemble à une mitose dans son déroulement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle sépare les chromatides sœurs, sans nouvelle réplication de l’ADN.', 8),
    ('cf88709c-f569-5d18-8a34-46f257545c36'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'Que signifie « réplication semi-conservative » ?', 'mcq', '["Chaque molécule fille garde un brin parental et un brin néoformé","Une molécule fille est ancienne, l’autre entièrement neuve","Les deux molécules filles sont entièrement neuves","Les brins parentaux se fragmentent au hasard"]'::jsonb, 0, 'C’est ce que l’expérience de Meselson et Stahl a établi.', 1),
    ('6a9508cf-434a-5fd8-b25b-c22887b5124b'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'Quelle enzyme synthétise le brin complémentaire lors de la réplication ?', 'mcq', '["L’ADN polymérase","L’ARN polymérase","L’ADN hélicase","La ligase seule"]'::jsonb, 0, 'Elle respecte l’appariement A-T et C-G.', 2),
    ('a5e59a16-dbf5-5b18-b2a2-dd64d045b3b7'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'L’ADN hélicase ouvre la double hélice au niveau des origines de réplication.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle forme un œil de réplication bordé de deux fourches.', 3),
    ('a7c78373-9678-5247-b07e-627087b80adb'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'Pourquoi la réplication démarre-t-elle en de multiples origines chez les eucaryotes ?', 'mcq', '["Pour copier un génome très long en un temps compatible avec le cycle cellulaire","Parce que l’ADN polymérase est lente à démarrer","Pour éviter les mutations","Parce que les chromosomes sont circulaires"]'::jsonb, 0, 'Trois milliards de paires de bases à partir d’une seule origine prendraient des semaines.', 4),
    ('d2c8bff7-1c44-5726-b4fe-117810465835'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'La réplication de l’ADN est parfaitement fidèle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il subsiste environ une erreur par milliard de nucléotides : c’est une mutation.', 5),
    ('7fe185ae-a7cc-5213-83a2-48bde15e1519'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'Quel agent mutagène provoque la soudure de deux bases voisines d’un même brin ?', 'mcq', '["Les rayons ultraviolets","Les rayons X uniquement","La chaleur","Le froid"]'::jsonb, 0, 'Les dimères de thymine ainsi formés bloquent la réplication.', 6),
    ('d406a52a-f3aa-5450-a89b-6d03dfc85be9'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'Quelle base s’apparie avec la cytosine ?', 'mcq', '["La guanine","L’adénine","La thymine","L’uracile"]'::jsonb, 0, 'C-G d’un côté, A-T de l’autre : l’appariement est strict.', 7),
    ('c96e3e20-2191-5880-a2cc-3003a8ba78b2'::uuid, 'c4d5153e-5692-5434-ad77-76b5ca7b90ff'::uuid, 'Sans mutation, l’évolution des espèces serait impossible.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La mutation est la source première de la variabilité génétique.', 8),
    ('57bb9c78-e223-508b-bcb4-92249ecb3a06'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Où se déroule la transcription chez les eucaryotes ?', 'mcq', '["Dans le noyau","Dans le cytoplasme","Dans le ribosome","Dans la mitochondrie uniquement"]'::jsonb, 0, 'L’ARN messager rejoint ensuite le cytoplasme pour être traduit.', 1),
    ('ebcd4a11-55b6-5e04-9c1d-566c8295c3de'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Quelle base remplace la thymine dans l’ARN ?', 'mcq', '["L’uracile","La guanine","La cytosine","L’adénine"]'::jsonb, 0, 'C’est l’une des trois différences entre ADN et ARN.', 2),
    ('3a35c327-3b7f-540c-b063-17303f5d5451'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Qu’est-ce que l’épissage ?', 'mcq', '["L’excision des introns et le raboutage des exons","La copie de l’ADN en ARN","La lecture de l’ARN par le ribosome","La réparation de l’ADN"]'::jsonb, 0, 'Il transforme le pré-messager en ARN messager mature.', 3),
    ('5be9196e-ce59-5598-b8b3-959283cb5e1b'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'L’épissage alternatif permet à un seul gène de coder plusieurs protéines.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une des raisons pour lesquelles les protéines sont bien plus nombreuses que les gènes.', 4),
    ('4deb351c-08a2-5f20-bce5-cdb808fce95a'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Combien de nucléotides forment un codon ?', 'mcq', '["Trois","Deux","Quatre","Un"]'::jsonb, 0, '64 codons possibles pour 20 acides aminés.', 5),
    ('4b2aad05-378d-5812-8805-666c230e6d4c'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Que signifie « le code génétique est redondant » ?', 'mcq', '["Plusieurs codons différents codent le même acide aminé","Un codon peut coder plusieurs acides aminés","Le code varie selon les espèces","Chaque gène est présent en double"]'::jsonb, 0, 'C’est ce qui rend possibles les mutations silencieuses.', 6),
    ('80609411-be9d-5bf8-a8d2-4d9e6ef9574f'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Un même codon peut coder plusieurs acides aminés différents.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le code est NON AMBIGU : un codon, un seul acide aminé.', 7),
    ('6c1a7df7-8505-57f9-9a5a-4fa3ac39ec09'::uuid, '535ab7ac-dbe8-5b2a-abaa-0a98fdde7298'::uuid, 'Quelle molécule apporte l’acide aminé correspondant à un codon ?', 'mcq', '["L’ARN de transfert","L’ARN messager","L’ADN polymérase","Le ribosome lui-même"]'::jsonb, 0, 'Son anticodon s’apparie au codon de l’ARN messager.', 8),
    ('0ec060dc-7466-579a-8e2b-97c63f708137'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Quels sont les trois grands types de mutation ponctuelle ?', 'mcq', '["Substitution, délétion, insertion","Transcription, traduction, réplication","Mitose, méiose, fécondation","Duplication, translocation, fusion"]'::jsonb, 0, 'Ils modifient la séquence de nucléotides de manières différentes.', 1),
    ('ac5548c9-c9dc-5544-b58f-d98502b7b129'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Pourquoi une délétion d’un seul nucléotide est-elle souvent plus grave qu’une substitution ?', 'mcq', '["Parce qu’elle décale le cadre de lecture de toute la suite du gène","Parce qu’elle supprime le gène entier","Parce qu’elle empêche la réplication","Parce qu’elle touche toujours un codon stop"]'::jsonb, 0, 'Tous les codons suivants sont lus différemment.', 2),
    ('1bf30ebe-1b4f-50a0-814d-c3aca394f72f'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Une mutation silencieuse ne modifie pas la protéine produite.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le codon muté reste synonyme grâce à la redondance du code génétique.', 3),
    ('cc338c3a-cfd2-5191-8e49-359eef7c11e0'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Qu’est-ce qu’une mutation non-sens ?', 'mcq', '["Une mutation qui fait apparaître un codon stop prématuré","Une mutation sans effet","Une mutation qui remplace un acide aminé","Une mutation dans un intron"]'::jsonb, 0, 'La protéine est tronquée, le plus souvent non fonctionnelle.', 4),
    ('a80b11d1-b07e-5e99-a8df-e30f5f17fd9e'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Une mutation somatique est transmise à la descendance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seules les mutations GERMINALES sont transmissibles.', 5),
    ('b9287b42-a029-5e69-a50d-3e46b8a00932'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Qu’est-ce que la dérive génétique ?', 'mcq', '["Une variation aléatoire des fréquences alléliques, surtout marquée dans les petites populations","La sélection des individus les mieux adaptés","La migration d’individus entre populations","L’apparition d’une nouvelle mutation"]'::jsonb, 0, 'Le hasard y pèse davantage que la sélection.', 6),
    ('7c93355b-6a90-5825-9fca-e2f92728c689'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Que sont des allèles ?', 'mcq', '["Des versions différentes d’un même gène","Des gènes situés sur des chromosomes différents","Des protéines de même fonction","Des séquences non codantes"]'::jsonb, 0, 'Ils naissent de l’accumulation des mutations.', 7),
    ('863640c2-3ee3-5ea2-a768-0bbbfaeda48c'::uuid, '4544c301-cacb-5944-bb2f-31959b5b0a87'::uuid, 'Un allèle avantageux dans un environnement peut être défavorable dans un autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’allèle drépanocytaire protège du paludisme mais entraîne une maladie grave à l’état homozygote.', 8),
    ('75a7f645-f48e-5f0f-835c-a8189ae989ba'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Que trace l’ADN mitochondrial ?', 'mcq', '["La lignée maternelle","La lignée paternelle","Les deux lignées","Aucune lignée"]'::jsonb, 0, 'Il est transmis uniquement par la mère.', 1),
    ('e4563df6-224c-50d0-9db0-3dc14c64618e'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Où la diversité génétique humaine est-elle la plus grande ?', 'mcq', '["En Afrique","En Europe","En Asie","En Océanie"]'::jsonb, 0, 'C’est un argument majeur en faveur de l’origine africaine d’Homo sapiens.', 2),
    ('e9cdd667-c65f-5d72-975c-ad829134a0c6'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Les populations non africaines actuelles portent quelques pour cent d’ADN néandertalien.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’ADN fossile a mis en évidence ces métissages.', 3),
    ('993e8b8b-1513-575c-a9fd-802597db41b7'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Qu’est-ce que l’horloge moléculaire ?', 'mcq', '["L’usage du taux de mutation pour dater la divergence entre deux lignées","La mesure du rythme circadien","La durée d’un cycle cellulaire","La vitesse de la réplication de l’ADN"]'::jsonb, 0, 'Plus les génomes diffèrent, plus la divergence est ancienne.', 4),
    ('9e758cb2-2885-50f8-b8f9-3db7d3789ed2'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Quelle adaptation récente s’observe dans les populations d’éleveurs ?', 'mcq', '["La persistance de la lactase à l’âge adulte","La résistance au froid extrême","Une vision nocturne accrue","Une taille plus élevée"]'::jsonb, 0, 'Elle permet de digérer le lait après le sevrage.', 5),
    ('4e614557-ced3-5a16-b3ce-86b33ae83a91'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'La variabilité génétique entre deux individus d’une même population est en moyenne plus faible qu’entre deux populations.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : la variabilité intrapopulationnelle domine largement.', 6),
    ('244f6c12-ace8-5cc1-bc6e-b7000146766b'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Que transmet le chromosome Y ?', 'mcq', '["Une information suivant la lignée paternelle","L’information maternelle","L’ensemble du génome","Les mitochondries"]'::jsonb, 0, 'Il passe de père en fils, sans recombinaison sur l’essentiel de sa longueur.', 7),
    ('c37a35b2-f540-5df2-a68a-37c24d624047'::uuid, '284b0f7d-c811-53f5-98e5-8b1e04c840f7'::uuid, 'Il y a combien de temps, environ, Homo sapiens est-il apparu en Afrique ?', 'mcq', '["Environ 300 000 ans","Environ 30 000 ans","Environ 3 millions d’années","Environ 10 000 ans"]'::jsonb, 0, 'Les fossiles du Jebel Irhoud, au Maroc, en sont un jalon.', 8),
    ('e11788df-053b-515c-a0c4-aeff1458a40d'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'Qu’est-ce qu’une enzyme ?', 'mcq', '["Une protéine qui catalyse une réaction sans être consommée","Un glucide énergétique","Un lipide membranaire","Une molécule d’ARN structurale"]'::jsonb, 0, 'Elle accélère la réaction sans en modifier le bilan.', 1),
    ('bd764949-5c1a-53d6-9904-f941a6b994e3'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'Quelles sont les deux spécificités d’une enzyme ?', 'mcq', '["Spécificité de substrat et spécificité d’action","Spécificité de température et de pH","Spécificité de cellule et de tissu","Spécificité d’espèce et d’organe"]'::jsonb, 0, 'Elle ne reconnaît qu’un substrat et ne catalyse qu’un type de réaction.', 2),
    ('bdb236b8-4afd-59ed-a97a-82817bfb0f47'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'L’enzyme est consommée au cours de la réaction qu’elle catalyse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est régénérée intacte et peut recommencer aussitôt.', 3),
    ('fc2148f0-25a0-5cde-a39e-bc24a599d5f8'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'Que se passe-t-il quand la température dépasse largement l’optimum d’une enzyme ?', 'mcq', '["La protéine se dénature et l’activité chute","L’activité continue d’augmenter","Le substrat change de nature","La spécificité disparaît sans perte d’activité"]'::jsonb, 0, 'La structure tridimensionnelle du site actif est détruite.', 4),
    ('44406098-4ea1-5872-b0a7-d27587ebaea4'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'Pourquoi l’activité enzymatique atteint-elle un plateau quand on augmente la concentration en substrat ?', 'mcq', '["Parce que tous les sites actifs sont occupés","Parce que le substrat devient toxique","Parce que le pH change","Parce que l’enzyme est consommée"]'::jsonb, 0, 'C’est la saturation de l’enzyme.', 5),
    ('8d465f44-68bf-53a5-899b-c4362a384c2d'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'La pepsine et l’amylase salivaire ont le même pH optimal.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La pepsine travaille en milieu très acide, l’amylase à pH proche de la neutralité.', 6),
    ('027d855f-340e-5b4f-a1bd-bf6d4287d182'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'Comment agit un inhibiteur compétitif ?', 'mcq', '["Il occupe le site actif à la place du substrat","Il détruit l’enzyme","Il augmente la température","Il modifie le substrat"]'::jsonb, 0, 'Beaucoup de médicaments exploitent ce mécanisme.', 7),
    ('3d157910-dfe2-5a6d-9402-bad4c768c76b'::uuid, 'c4b437d2-bd52-5a21-b1bd-89c5169d43e7'::uuid, 'Une mutation d’un gène codant une enzyme peut bloquer toute une voie métabolique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La phénylcétonurie en est un exemple : l’enzyme déficiente interrompt une dégradation.', 8),
    ('0c007edc-23fb-529f-82f4-975933c69cfe'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'Que montre la courbe hypsométrique du globe terrestre ?', 'mcq', '["Deux maxima d’altitude, correspondant aux continents et aux océans","Une répartition uniforme des altitudes","Un maximum unique proche du niveau de la mer","Trois maxima distincts"]'::jsonb, 0, 'Cette bimodalité traduit deux types de croûte de nature différente.', 1),
    ('fba4396b-e1fb-585e-a01d-ef1f0175bd5d'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'De quelles roches la croûte océanique est-elle principalement constituée ?', 'mcq', '["Basaltes et gabbros","Granites et gneiss","Calcaires et grès","Péridotites"]'::jsonb, 0, 'Elles sont plus denses et plus riches en fer et magnésium que les granites.', 2),
    ('a97b49fa-8af8-598e-a169-1bf21696c409'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'La croûte continentale est plus dense que la croûte océanique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est moins dense (environ 2,7 contre 2,9), ce qui explique qu’elle flotte plus haut.', 3),
    ('94c95afd-0ad8-55e6-9196-c9e296212233'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'Quel est l’âge maximal de la croûte océanique actuelle ?', 'mcq', '["Environ 200 millions d’années","Environ 4 milliards d’années","Environ 2 milliards d’années","Environ 10 millions d’années"]'::jsonb, 0, 'Elle est constamment renouvelée, alors que la croûte continentale est conservée.', 4),
    ('ca39b5fe-9497-59d6-b61c-36a27d336f85'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'Qu’est-ce que l’équilibre isostatique ?', 'mcq', '["L’équilibre des blocs crustaux flottant sur le manteau ductile","L’équilibre des températures dans le globe","L’égalité des masses entre continents et océans","La stabilité des plaques tectoniques"]'::jsonb, 0, 'Comparable à celui d’un iceberg flottant sur l’eau.', 5),
    ('76e8a558-1fbc-521e-9711-36eb29244e4d'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'Une chaîne de montagnes est soutenue par une racine crustale profonde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La croûte y atteint jusqu’à 70 km d’épaisseur.', 6),
    ('8defeb7c-1d92-54fc-a54b-96ecabf10ebc'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'Pourquoi la Scandinavie s’élève-t-elle encore aujourd’hui ?', 'mcq', '["Parce que le continent, allégé par la fonte de la calotte glaciaire, remonte","Parce qu’un volcan la soulève","Parce que la mer se retire","Parce que deux plaques y entrent en collision"]'::jsonb, 0, 'C’est un rééquilibrage isostatique en cours depuis la fin de la dernière glaciation.', 7),
    ('cd4228f5-070c-5d28-ade5-20d9e24c4def'::uuid, 'c6119034-a83c-5bab-a678-17ed0641528b'::uuid, 'Quelle est l’épaisseur moyenne de la croûte océanique ?', 'mcq', '["Environ 7 km","Environ 30 km","Environ 70 km","Environ 100 km"]'::jsonb, 0, 'Bien plus mince que la croûte continentale.', 8),
    ('23050a95-7d1e-5394-acda-c6c6716470d8'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'Quelle onde sismique ne se propage pas dans les liquides ?', 'mcq', '["L’onde S","L’onde P","Les deux","Aucune des deux"]'::jsonb, 0, 'Son absence au-delà de 103° a révélé que le noyau externe est liquide.', 1),
    ('1f8a993b-58e6-552d-b652-3fb565e2bd10'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'Que sépare la discontinuité de Mohorovičić ?', 'mcq', '["La croûte et le manteau","Le manteau et le noyau externe","Le noyau externe et la graine","La lithosphère et l’asthénosphère"]'::jsonb, 0, 'Les ondes sismiques y accélèrent brutalement.', 2),
    ('58577307-e73d-54fc-bfef-fa1a69f738f9'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'Le noyau externe de la Terre est liquide.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’extinction des ondes S à la discontinuité de Gutenberg le démontre.', 3),
    ('a8d88077-7f23-56e8-9c06-47aa4f15d4e0'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'Qu’est-ce que la lithosphère ?', 'mcq', '["La couche rigide formée par la croûte et le sommet du manteau","La croûte seule","Le manteau entier","La couche ductile sous les plaques"]'::jsonb, 0, 'C’est l’unité mécanique qui constitue les plaques tectoniques.', 4),
    ('470a1463-f38e-53d1-bd8f-a6a1b3659982'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'La distinction croûte/manteau/noyau est de nature chimique, celle lithosphère/asthénosphère de nature mécanique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ne pas les confondre est une exigence classique du programme.', 5),
    ('51f831fd-dde2-56bd-b3f5-754b6eea5698'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'Pourquoi les ondes ralentissent-elles dans l’asthénosphère ?', 'mcq', '["Parce qu’elle est ductile, partiellement fondue","Parce qu’elle est plus froide","Parce qu’elle est plus dense","Parce qu’elle est liquide en totalité"]'::jsonb, 0, 'C’est la LVZ, zone à faible vitesse.', 6),
    ('0296f105-aa68-59f5-8f1b-87fb1d3f129e'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'À quelle profondeur se situe la discontinuité de Gutenberg ?', 'mcq', '["Environ 2 900 km","Environ 100 km","Environ 5 100 km","Environ 700 km"]'::jsonb, 0, 'Elle marque la limite manteau / noyau externe.', 7),
    ('3d081537-9857-5dfe-ac78-427e453a40ca'::uuid, 'e417ed49-5546-5e22-91b8-9876978bf23e'::uuid, 'La zone d’ombre sismique s’explique par la réfraction des ondes à l’entrée du noyau.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ondes P déviées et ondes S éteintes créent cette bande sans enregistrement direct.', 8),
    ('7a26b313-cd94-5174-880f-61afb0e7335b'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'Quelle est la principale source de la chaleur interne de la Terre ?', 'mcq', '["La radioactivité naturelle des roches","Le rayonnement solaire","Les marées océaniques","Les impacts de météorites"]'::jsonb, 0, 'Elle fournit environ 80 % du flux, le reste étant la chaleur résiduelle.', 1),
    ('308383b8-53d2-550a-b891-182db6654422'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'Quel mode de transfert thermique domine dans la lithosphère ?', 'mcq', '["La conduction","La convection","Le rayonnement","L’advection"]'::jsonb, 0, 'La lithosphère est rigide : la chaleur s’y transmet de proche en proche.', 2),
    ('c33f46cb-8c5a-5090-846c-5bdff6109920'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'La convection implique un déplacement de matière.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui la rend bien plus efficace que la conduction.', 3),
    ('9827582b-e734-5874-9aa7-d66997518fde'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'Où le flux géothermique est-il le plus élevé ?', 'mcq', '["Au niveau des dorsales océaniques","Au centre des vieux continents","Dans les fosses océaniques profondes","Sous les calottes glaciaires"]'::jsonb, 0, 'Le matériel mantellique chaud y remonte près de la surface.', 4),
    ('b69f71fc-9b2a-5d1b-acd1-74e499733a01'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'Le manteau terrestre est liquide, ce qui explique la convection.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est SOLIDE mais ductile : il flue lentement, de quelques centimètres par an.', 5),
    ('72659186-6a73-58cd-a50e-64a9b2a8b2c8'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'Que devient la lithosphère océanique en s’éloignant de la dorsale ?', 'mcq', '["Elle se refroidit, s’épaissit et devient plus dense","Elle se réchauffe et s’allège","Elle reste identique","Elle se dissout dans l’asthénosphère"]'::jsonb, 0, 'C’est ce qui rend possible sa plongée en subduction.', 6),
    ('8c437fac-7937-51df-90c6-9843812b9907'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'Quel élément radioactif contribue au flux géothermique ?', 'mcq', '["Le potassium 40","Le carbone 14","L’hélium 3","Le fer 56"]'::jsonb, 0, 'Avec l’uranium et le thorium, il chauffe l’intérieur du globe.', 7),
    ('329d318f-0ee5-5dec-81f7-f50eb204e8c7'::uuid, '7a9e9051-8b70-561c-a173-e5a2ec6f1515'::uuid, 'La convection mantellique est un des moteurs du déplacement des plaques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'S’y ajoute la traction exercée par la plaque plongeante en subduction.', 8),
    ('fcbdfab0-cba7-53ef-a7d3-e75a462e484d'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Quel argument N’A PAS été utilisé par Wegener en 1912 ?', 'mcq', '["Les anomalies magnétiques du plancher océanique","La forme complémentaire des côtes","La répartition de fossiles identiques","Les traces d’une glaciation commune"]'::jsonb, 0, 'Elles n’ont été découvertes qu’en 1963, par Vine et Matthews.', 1),
    ('179a7d48-9980-520c-a4d8-72330a10ebd9'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Pourquoi l’hypothèse de Wegener a-t-elle été rejetée ?', 'mcq', '["Parce qu’aucun mécanisme plausible n’expliquait le déplacement","Parce que ses observations étaient fausses","Parce que les fossiles étaient mal datés","Parce que les continents étaient jugés immobiles par la religion"]'::jsonb, 0, 'On ne voyait pas comment un continent traverserait un plancher rigide.', 2),
    ('72c01789-5b8f-518f-952b-bf5d0452c7c2'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Les anomalies magnétiques du plancher océanique sont symétriques de part et d’autre de la dorsale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles enregistrent les inversions du champ magnétique au fil de l’expansion.', 3),
    ('d1fbb745-92ae-56e1-9c79-af1cf2abbfa0'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Qui a proposé l’expansion des fonds océaniques en 1962 ?', 'mcq', '["Harry Hess","Alfred Wegener","Andrija Mohorovičić","Inge Lehmann"]'::jsonb, 0, 'La croûte naît à la dorsale et disparaît dans les fosses.', 4),
    ('f785d3d6-bfdc-57d0-976c-f3fb8c431b26'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Que montre l’âge des sédiments les plus profonds d’un forage océanique ?', 'mcq', '["Il augmente avec la distance à la dorsale","Il est identique partout","Il diminue avec la distance à la dorsale","Il dépasse toujours un milliard d’années"]'::jsonb, 0, 'C’est une confirmation directe de l’expansion océanique.', 5),
    ('504f0e23-3452-5e03-9b1c-8b49761d391b'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Que permet d’estimer un alignement de volcans de point chaud ?', 'mcq', '["Le sens et la vitesse de déplacement de la plaque","L’âge de la Terre","L’épaisseur de la croûte continentale","La température du noyau"]'::jsonb, 0, 'La chaîne d’Hawaï en est l’exemple canonique.', 6),
    ('12780b29-39da-56a3-abef-c3bb715412ce'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Quel ordre de grandeur ont les vitesses de déplacement des plaques mesurées par GPS ?', 'mcq', '["Quelques centimètres par an","Quelques mètres par an","Quelques millimètres par siècle","Quelques kilomètres par an"]'::jsonb, 0, 'Cohérent avec les vitesses déduites des anomalies magnétiques.', 7),
    ('4e449afc-703b-583f-ace6-b2dc34d69aae'::uuid, 'ef11aaaf-7919-58ea-af2f-3147f7495ad1'::uuid, 'Les frontières de plaques sont soulignées par la sismicité et le volcanisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Leur carte dessine les plaques bien mieux que le contour des continents.', 8),
    ('e3589b21-fe01-569a-a2ec-aa4d2027a6c0'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Quel mécanisme produit le magma au niveau des dorsales ?', 'mcq', '["La fusion partielle de la péridotite par décompression","Un apport de chaleur venu du noyau","La fusion de la croûte continentale","La cristallisation du basalte"]'::jsonb, 0, 'C’est la baisse de pression, et non une hausse de température, qui déclenche la fusion.', 1),
    ('7f320be1-a70e-5143-b60e-db74087b3603'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Quelle roche se forme quand le magma basaltique refroidit lentement en profondeur ?', 'mcq', '["Le gabbro","Le basalte","Le granite","La péridotite"]'::jsonb, 0, 'Le refroidissement lent permet une cristallisation complète : structure grenue.', 2),
    ('d3a62599-e80e-5c5e-82b4-1d902bebf165'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Basalte et gabbro proviennent du même magma.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seule la vitesse de refroidissement diffère, donc la texture.', 3),
    ('e6df5591-1de5-51f3-8368-f2913631d535'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Quel type de faille domine au niveau d’une dorsale ?', 'mcq', '["Les failles normales","Les failles inverses","Les failles décrochantes uniquement","Aucune faille"]'::jsonb, 0, 'Elles sont la signature d’un contexte d’extension.', 4),
    ('da020797-791a-5e52-ac67-502facd3814d'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'La sismicité des dorsales est profonde et de forte magnitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est SUPERFICIELLE et de magnitude modérée.', 5),
    ('31e8bcbb-65a5-507a-be4e-c942b0d21ca1'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Que sont les fumeurs noirs ?', 'mcq', '["Des sources hydrothermales sous-marines riches en métaux","Des volcans terrestres explosifs","Des panaches de cendres volcaniques","Des cheminées de subduction"]'::jsonb, 0, 'Ils abritent des écosystèmes indépendants de la lumière solaire.', 6),
    ('d9464bf6-965a-5bb1-816f-faf77b05f5c1'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Qu’est-ce qui distingue une dorsale rapide d’une dorsale lente ?', 'mcq', '["La dorsale lente présente un rift axial profond","La dorsale rapide produit du granite","La dorsale lente ne produit pas de magma","La dorsale rapide est asismique"]'::jsonb, 0, 'L’Atlantique, lente, a un rift marqué ; le Pacifique est, rapide, un profil bombé.', 7),
    ('ec3b0203-4152-5db0-9d9c-7b2ac6cb15c5'::uuid, '574399f9-71b1-51ce-aa7b-4759c9c09d2b'::uuid, 'Les pillow lavas se forment par refroidissement brutal du basalte au contact de l’eau de mer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ces coussins sont caractéristiques du volcanisme sous-marin.', 8),
    ('d9fb145e-ea85-50ba-94e0-f802ea8a1628'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Pourquoi une lithosphère océanique âgée plonge-t-elle en subduction ?', 'mcq', '["Parce que sa densité dépasse celle de l’asthénosphère","Parce qu’elle est plus chaude","Parce qu’elle est poussée par la dorsale seule","Parce qu’elle est plus fine"]'::jsonb, 0, 'Le refroidissement l’épaissit et l’alourdit jusqu’à l’instabilité.', 1),
    ('74d5eb44-fe44-5e9f-b3c3-0495ee61ec9b'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Qu’est-ce que le plan de Wadati-Benioff ?', 'mcq', '["Le plan incliné sur lequel se répartissent les foyers sismiques d’une subduction","La limite croûte-manteau","Le plan d’une faille transformante","La surface d’un prisme d’accrétion"]'::jsonb, 0, 'Il matérialise la plaque plongeante jusqu’à environ 700 km.', 2),
    ('e6af2133-32a4-52ae-b645-34fb84852e37'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Le magma des zones de subduction provient de la fusion de la plaque plongeante.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il provient de la fusion du MANTEAU sus-jacent, hydraté par l’eau libérée par la plaque.', 3),
    ('abe37628-eafa-5ea6-87cd-ee61f25d9eb4'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Quel rôle joue l’eau dans le magmatisme de subduction ?', 'mcq', '["Elle abaisse la température de fusion du manteau","Elle refroidit le magma","Elle augmente la densité de la plaque","Elle empêche toute fusion"]'::jsonb, 0, 'Libérée par les transformations métamorphiques, elle déclenche la fusion partielle.', 4),
    ('8764084a-48e2-5a5c-a39e-cff019baecb5'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Pourquoi le volcanisme de subduction est-il explosif ?', 'mcq', '["Parce que le magma, visqueux et riche en gaz, les libère brutalement","Parce que le magma est très fluide","Parce que l’eau de mer entre en contact avec la lave","Parce que les éruptions sont sous-marines"]'::jsonb, 0, 'La viscosité piège les gaz jusqu’à la rupture.', 5),
    ('46edf7f2-bf45-5e9d-a975-4a338c678300'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Qu’est-ce qu’un prisme d’accrétion ?', 'mcq', '["Un empilement de sédiments raclés sur la plaque plongeante","Un volcan sous-marin","Une racine crustale de montagne","Une chambre magmatique"]'::jsonb, 0, 'Il se forme à l’avant de la plaque chevauchante.', 6),
    ('99b30729-2702-5b46-9e81-f56e5b5583ba'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Une anomalie thermique négative caractérise les zones de subduction.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La plaque plongeante est froide : elle abaisse localement le flux géothermique.', 7),
    ('06f9255a-4613-55d5-b9ea-41fd9e16cf19'::uuid, '070d9881-056a-52d0-b013-dce8a5c483d4'::uuid, 'Quelle roche magmatique de subduction se forme en profondeur ?', 'mcq', '["La granodiorite","L’andésite","Le basalte en coussins","La péridotite"]'::jsonb, 0, 'En surface, le même magma donne des andésites et des rhyolites.', 8),
    ('f6d21c8c-56dd-57a5-bbc5-28bdcbd8d21d'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Que sont les ophiolites ?', 'mcq', '["Des fragments de lithosphère océanique charriés dans une chaîne de montagnes","Des roches volcaniques de subduction","Des sédiments de fond de fosse","Des minéraux du manteau profond"]'::jsonb, 0, 'Leur présence en altitude prouve la disparition d’un ancien océan.', 1),
    ('e32aceea-3960-5116-9742-9f42bd5b7697'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Quel type de faille témoigne d’un raccourcissement en collision ?', 'mcq', '["La faille inverse","La faille normale","La faille transformante","Aucune faille"]'::jsonb, 0, 'Elle empile les unités et épaissit la croûte.', 2),
    ('6e6d7333-37b4-57a0-8abf-6cdaeecb48b1'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'La croûte continentale peut subduire aussi facilement que la croûte océanique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Trop peu dense, elle résiste à l’enfouissement : d’où la collision et l’épaississement.', 3),
    ('8402afa4-34c9-5e4c-9bdf-4d84b0266028'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Qu’est-ce que le métamorphisme ?', 'mcq', '["La transformation minéralogique d’une roche à l’état solide sous l’effet de la pression et de la température","La fusion complète d’une roche","L’altération chimique par l’eau de pluie","Le dépôt de sédiments en couches"]'::jsonb, 0, 'Les minéraux nouveaux permettent de reconstituer l’histoire de l’enfouissement.', 4),
    ('fa3f6776-4e23-5ea6-a3d3-d49645f0f938'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Que révèle la présence de blocs basculés et de failles normales fossiles dans une chaîne ?', 'mcq', '["Une ancienne marge passive, témoin de l’ouverture d’un océan","Une ancienne zone de subduction","Un ancien point chaud","Une ancienne calotte glaciaire"]'::jsonb, 0, 'C’est le témoin du stade initial du cycle de Wilson.', 5),
    ('0fd0924a-24e6-53c7-8113-6b38c0ce5fcc'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Une chaîne de montagnes possède une racine crustale profonde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle peut atteindre 70 km : c’est elle qui soutient le relief par isostasie.', 6),
    ('644fa87b-4452-52a4-95b6-789b76bb9a0d'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Quels processus font disparaître une chaîne de montagnes ?', 'mcq', '["L’érosion et le rééquilibrage isostatique","La subduction et le volcanisme","La sédimentation et le métamorphisme","L’expansion océanique"]'::jsonb, 0, 'Le second fait remonter les roches profondes à mesure que le sommet s’allège.', 7),
    ('a260e930-a7bf-5c53-aa5c-46c418918b9e'::uuid, 'c8e18008-25b7-52c6-a44f-d1e7a917d92e'::uuid, 'Qu’est-ce qu’une nappe de charriage ?', 'mcq', '["Un ensemble de terrains déplacé horizontalement sur des dizaines de kilomètres","Une couche de sédiments marins","Une coulée de lave fluide","Un glacier de vallée"]'::jsonb, 0, 'C’est une structure caractéristique des chaînes de collision.', 8),
    ('85e6838d-7f68-54c0-8b70-64cb14497f73'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'De quoi est composé un écosystème ?', 'mcq', '["D’une biocénose, d’un biotope et de leurs interactions","Des seuls animaux d’un milieu","Du seul milieu physico-chimique","D’une population unique et de son territoire"]'::jsonb, 0, 'Les interactions font partie intégrante de la définition.', 1),
    ('e1da566b-8f22-59b7-899a-285aa275f10e'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'Qu’est-ce qu’une relation de mutualisme ?', 'mcq', '["Une interaction bénéfique aux deux partenaires","Une interaction où l’un se nourrit de l’autre","Une interaction où l’un profite sans nuire à l’autre","Une compétition pour une ressource"]'::jsonb, 0, 'Les mycorhizes en sont l’exemple le plus étudié.', 2),
    ('2c503b0a-1b93-5bcb-a914-630132b5a22d'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'L’énergie circule en boucle fermée dans un écosystème.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la MATIÈRE qui circule en boucle ; l’énergie se dégrade et doit être renouvelée.', 3),
    ('bc969495-7f4e-5f32-bed5-02b87dddb542'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'Quelle part de l’énergie passe environ d’un niveau trophique au suivant ?', 'mcq', '["Environ 10 %","Environ 50 %","Environ 90 %","La totalité"]'::jsonb, 0, 'Cette déperdition limite le nombre de maillons d’une chaîne alimentaire.', 4),
    ('9f4a5f71-3d41-5202-98a1-2497e94848e5'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'Quel est le rôle des décomposeurs ?', 'mcq', '["Minéraliser la matière organique morte et restituer les éléments au milieu","Produire de la matière organique par photosynthèse","Consommer les producteurs primaires","Fixer l’énergie lumineuse"]'::jsonb, 0, 'Sans eux, le cycle de la matière serait interrompu.', 5),
    ('6b025b56-1c09-5712-be2b-f66c555a08a7'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'Qu’est-ce que la résilience d’un écosystème ?', 'mcq', '["Sa capacité à retrouver un fonctionnement comparable après une perturbation","Son absence totale de variation","Sa productivité maximale","Sa richesse en espèces"]'::jsonb, 0, 'Elle n’est pas illimitée : au-delà d’un seuil, l’écosystème bascule.', 6),
    ('57d439b6-22a0-5a67-b6ed-1cf38b7c21ce'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'Les mycorhizes associent un champignon et les racines d’une plante au bénéfice des deux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La plante fournit des sucres, le champignon améliore l’absorption d’eau et de sels minéraux.', 7),
    ('3494ec58-2c1c-5970-bb03-74d42f290ef9'::uuid, '784aea0a-1473-5c66-8fe6-d01537db03f2'::uuid, 'Qu’appelle-t-on succession écologique ?', 'mcq', '["L’enchaînement des communautés qui recolonisent un milieu après perturbation","Le remplacement d’un prédateur par un autre","La migration saisonnière des espèces","La disparition progressive d’un écosystème"]'::jsonb, 0, 'Du stade pionnier au stade mature, chaque stade prépare le suivant.', 8),
    ('516a452c-8e56-51b8-a94c-7998f98de990'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'À quelle catégorie appartient le service de pollinisation ?', 'mcq', '["Les services de régulation","Les services d’approvisionnement","Les services culturels","Les services de production"]'::jsonb, 0, 'Il régule le fonctionnement des cultures sans fournir directement un bien.', 1),
    ('4b66b774-6602-5ac7-ba23-2c9d995bc72a'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'Quelle est la première cause d’érosion de la biodiversité ?', 'mcq', '["La destruction et la fragmentation des habitats","Le changement climatique","La pollution plastique","Les espèces envahissantes"]'::jsonb, 0, 'Agriculture, urbanisation et déforestation en sont les moteurs principaux.', 2),
    ('cf017e45-a7d5-5a86-b6bb-af4edd00a99a'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'Le bois de construction est un service d’approvisionnement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme la nourriture, l’eau douce ou les molécules médicinales.', 3),
    ('9f8dc0a9-bef9-5b9a-b9b8-141d84e93d87'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'Qu’est-ce que l’eutrophisation ?', 'mcq', '["L’enrichissement excessif d’un milieu aquatique en nutriments","L’assèchement d’une zone humide","L’acidification des océans","L’introduction d’une espèce exotique"]'::jsonb, 0, 'Elle provoque une prolifération d’algues puis une désoxygénation du milieu.', 4),
    ('db736140-461a-50b1-9610-369de11508df'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'Une décision de gestion d’un écosystème est une décision purement scientifique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La science éclaire les options ; le choix relève du débat social.', 5),
    ('ea36d4d7-61bf-5b1b-a626-06dad34c6fb3'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'Qu’est-ce qu’un corridor écologique ?', 'mcq', '["Un espace reliant des habitats pour permettre la circulation des espèces","Une zone interdite à toute activité humaine","Un couloir de migration des oiseaux uniquement","Une bande de terre cultivée sans pesticides"]'::jsonb, 0, 'C’est le principe des trames verte et bleue, contre la fragmentation.', 6),
    ('79d7d516-b669-5082-b848-f46ebd0c135d'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'La valeur récréative et esthétique d’un paysage constitue un service écosystémique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un service culturel, au même titre que la valeur patrimoniale.', 7),
    ('02a1236c-1636-5bc1-bcef-94a5217afe38'::uuid, 'c70c5d0f-4c54-51eb-913b-381e1ca365cc'::uuid, 'Pourquoi la gestion d’un écosystème suppose-t-elle des arbitrages ?', 'mcq', '["Parce que maximiser un service se fait souvent au détriment d’un autre","Parce que les services sont tous équivalents","Parce que la science ne dispose d’aucune donnée","Parce que les écosystèmes sont indestructibles"]'::jsonb, 0, 'Produire plus de bois, par exemple, réduit la biodiversité forestière.', 8),
    ('b79372cf-9b20-5ef5-8771-1802388664a9'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Qu’est-ce qu’un porteur sain ?', 'mcq', '["Un individu hétérozygote qui ne développe pas la maladie mais peut la transmettre","Un individu guéri d’une maladie génétique","Un individu sans aucune mutation","Un individu atteint mais sans symptôme visible"]'::jsonb, 0, 'Il n’existe que pour les maladies récessives.', 1),
    ('ce42d99b-c990-52d0-9fa5-aa98dd523f55'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Deux parents non atteints ayant un enfant malade indiquent une transmission récessive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le repère de base pour lire un arbre généalogique.', 2),
    ('075aea06-d04f-5b96-9312-fe4ee6270da6'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Pourquoi les maladies liées à l’X touchent-elles surtout les garçons ?', 'mcq', '["Parce qu’ils ne possèdent qu’un seul chromosome X","Parce que le chromosome Y porte la mutation","Parce qu’ils héritent toujours de l’X paternel","Parce que leurs mutations sont plus fréquentes"]'::jsonb, 0, 'Sans second X, aucun allèle sain ne peut compenser.', 3),
    ('3bc19239-3a51-5221-9282-ba0ab40fb047'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Qu’est-ce qu’une maladie multifactorielle ?', 'mcq', '["Une maladie résultant de l’interaction entre plusieurs gènes et l’environnement","Une maladie causée par un seul gène","Une maladie infectieuse","Une maladie sans cause identifiable"]'::jsonb, 0, 'Diabète de type 2, obésité, hypertension en relèvent.', 4),
    ('bcc12f63-59a6-52e4-8c03-1a14e245cced'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Porter un allèle de prédisposition signifie que l’on développera nécessairement la maladie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela accroît la probabilité, sans la rendre certaine : le mode de vie compte.', 5),
    ('b2b34787-5f70-56f9-8c71-ec12b0f51308'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Quel outil permet de modifier une séquence d’ADN de manière ciblée ?', 'mcq', '["CRISPR-Cas9","L’électrophorèse","La PCR seule","Le microscope électronique"]'::jsonb, 0, 'Son usage sur les cellules germinales est strictement encadré par la loi.', 6),
    ('b38ede1c-1c9b-53a8-8db4-a5632ec58142'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Quel est le mode de transmission de la chorée de Huntington ?', 'mcq', '["Autosomique dominante","Autosomique récessive","Liée à l’X récessive","Liée à l’Y"]'::jsonb, 0, 'Un seul allèle muté suffit à provoquer la maladie.', 7),
    ('0550d976-9b8e-590f-8e20-cf9530072ca5'::uuid, 'b3bdd523-5d27-5348-b706-ab1e37b4a1e0'::uuid, 'Modifier le génome de cellules somatiques et celui de cellules germinales soulèvent les mêmes questions éthiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La modification germinale se transmet à la descendance : c’est ce qui change tout.', 8),
    ('1a05a5ec-9293-59c9-93f2-594e7b44d6c6'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Qu’est-ce qu’un oncogène ?', 'mcq', '["Un proto-oncogène muté devenu hyperactif, qui stimule la division cellulaire","Un gène qui freine la division cellulaire","Un gène de réparation de l’ADN","Un gène viral uniquement"]'::jsonb, 0, 'C’est l’accélérateur de la prolifération resté bloqué.', 1),
    ('5e654fdc-a7b0-5894-bee0-a1d9009d8a9b'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Quel gène suppresseur de tumeur est surnommé le « gardien du génome » ?', 'mcq', '["p53","BRCA1","RAS","MYC"]'::jsonb, 0, 'Il est muté dans une grande part des cancers humains.', 2),
    ('7ed6715f-adca-5ab8-b61f-45ea3276af04'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Une seule mutation suffit à transformer une cellule normale en cellule cancéreuse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La cancérisation est un processus multi-étapes qui accumule plusieurs mutations.', 3),
    ('9cf54e57-6305-5669-a21c-76947ba47a63'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Qu’est-ce que l’apoptose ?', 'mcq', '["La mort cellulaire programmée","La division cellulaire","La migration d’une cellule tumorale","La formation de nouveaux vaisseaux"]'::jsonb, 0, 'Sa mise en échec permet à la cellule anormale de survivre.', 4),
    ('ed7c9266-378f-5348-ab34-7f00e03f8061'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Qu’est-ce que l’angiogenèse tumorale ?', 'mcq', '["La formation de nouveaux vaisseaux sanguins irriguant la tumeur","La migration des cellules tumorales","La mort des cellules cancéreuses","La réparation de l’ADN"]'::jsonb, 0, 'Elle permet à la tumeur de croître au-delà de quelques millimètres.', 5),
    ('cf89bf72-cf82-5793-b3f9-753f2e172533'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Les mutations à l’origine d’un cancer sont le plus souvent somatiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles ne sont donc pas transmissibles ; seule une prédisposition peut l’être.', 6),
    ('1cbe4f13-fbfb-5f16-a1ee-886d55635266'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Quel est le premier facteur de risque évitable de cancer ?', 'mcq', '["Le tabac","Le stress","Le manque de sommeil","Les ondes électromagnétiques"]'::jsonb, 0, 'Il est impliqué dans une part majeure des cancers évitables.', 7),
    ('47a5ea97-efcd-523d-917e-73335d5c7a2c'::uuid, 'e433fc88-d67f-57b2-8772-6dd6c0e7d57d'::uuid, 'Que sont les métastases ?', 'mcq', '["Des colonies tumorales secondaires formées à distance de la tumeur d’origine","Les premières mutations d’une cellule","Des cellules immunitaires anticancéreuses","Des vaisseaux irriguant la tumeur"]'::jsonb, 0, 'Les cellules migrent par le sang ou la lymphe.', 8),
    ('4ee894c7-f9e1-548e-9907-da4823b92fc5'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Un antibiotique est-il efficace contre un virus ?', 'mcq', '["Non, il n’agit que sur les bactéries","Oui, sur tous les virus","Oui, mais seulement à forte dose","Uniquement sur les virus respiratoires"]'::jsonb, 0, 'Le prescrire contre une grippe est inutile et favorise les résistances.', 1),
    ('de868a06-729b-56a4-93a8-72781350c4dd'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'L’antibiotique provoque l’apparition de la mutation de résistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La mutation préexiste au hasard : l’antibiotique ne fait que la SÉLECTIONNER.', 2),
    ('bca4a01d-f0cf-5c97-beb8-f3392c292eae'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Qu’est-ce que la conjugaison bactérienne ?', 'mcq', '["Le transfert d’un plasmide d’une bactérie à une autre","La capture d’ADN libre dans le milieu","Le transport de gènes par un virus","La division d’une bactérie en deux"]'::jsonb, 0, 'Elle permet la diffusion rapide des gènes de résistance, même entre espèces.', 3),
    ('17fff0fe-2d40-5191-914b-f865338fbb37'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Comment s’appelle le transfert de gènes bactériens par un virus bactériophage ?', 'mcq', '["La transduction","La transformation","La conjugaison","La transcription"]'::jsonb, 0, 'Le virus emporte avec lui des fragments du génome bactérien.', 4),
    ('2169c832-719a-5b07-bbef-fb21c8eaa207'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Pourquoi l’arrêt prématuré d’un traitement antibiotique est-il dangereux ?', 'mcq', '["Il laisse survivre les bactéries les moins sensibles, qui se multiplient ensuite","Il détruit la flore intestinale","Il rend le patient allergique","Il transforme les bactéries en virus"]'::jsonb, 0, 'La population résiduelle est justement la plus résistante.', 5),
    ('c7aa865f-fd64-5b82-a4eb-f3ddf820cdc0'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Qu’est-ce qu’un antibiogramme ?', 'mcq', '["Un test de sensibilité d’une souche bactérienne aux différents antibiotiques","Une radiographie des poumons","Un dosage sanguin de l’antibiotique","Un vaccin contre les bactéries"]'::jsonb, 0, 'Il permet de cibler la molécule réellement efficace.', 6),
    ('ec294e02-7224-5814-9d8e-f318ebaefb66'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'La résistance aux antibiotiques est un exemple de sélection naturelle observable en laboratoire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les générations bactériennes se succèdent en quelques dizaines de minutes.', 7),
    ('7e666f15-5f81-5bd0-a49c-4b6ce83e6a54'::uuid, '471f782f-4ff4-55c2-bc53-a6d65fef0ba1'::uuid, 'Quel usage a longtemps accéléré la diffusion des résistances en dehors de la médecine humaine ?', 'mcq', '["L’usage massif d’antibiotiques en élevage","L’usage en agriculture céréalière","L’usage dans les produits ménagers","L’usage dans les cosmétiques"]'::jsonb, 0, 'Ils y ont longtemps été employés comme facteurs de croissance.', 8),
    ('a18cd820-d3a9-5c53-97c9-fca488a31036'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Quelles sont les caractéristiques de l’immunité innée ?', 'mcq', '["Immédiate, non spécifique et sans mémoire","Lente, spécifique et avec mémoire","Immédiate, spécifique et avec mémoire","Lente, non spécifique et avec mémoire"]'::jsonb, 0, 'Elle est présente dès la naissance et commune à tous les animaux.', 1),
    ('dac72c05-33e2-58e5-b331-4f42c4e9fcec'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Quels sont les quatre signes de la réaction inflammatoire aiguë ?', 'mcq', '["Rougeur, chaleur, gonflement, douleur","Fièvre, toux, fatigue, douleur","Rougeur, démangeaison, pâleur, fièvre","Gonflement, fièvre, éruption, frissons"]'::jsonb, 0, 'Ils sont décrits depuis l’Antiquité.', 2),
    ('d861e1cf-3cf0-566b-a9bf-ec1f45ac13e8'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'La réaction inflammatoire est spécifique de l’agent infectieux rencontré.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est stéréotypée : la même réponse quel que soit l’intrus.', 3),
    ('6aa161c7-8c0b-5c32-9343-2204a9a0c427'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Quelles sont les quatre étapes de la phagocytose ?', 'mcq', '["Adhésion, ingestion, digestion, élimination des débris","Reconnaissance, division, migration, mémoire","Adhésion, division, sécrétion, apoptose","Ingestion, multiplication, migration, présentation"]'::jsonb, 0, 'La digestion a lieu dans le phagolysosome.', 4),
    ('c01d2e81-728e-55e8-b463-fc56f1f77032'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Quelle cellule fait le lien entre immunité innée et immunité adaptative ?', 'mcq', '["La cellule dendritique","Le globule rouge","La plaquette","Le lymphocyte B naïf"]'::jsonb, 0, 'Elle migre vers un ganglion et y présente l’antigène.', 5),
    ('f9e0ab80-b97c-59e1-a946-a86cd94cb43c'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Comment les cellules sentinelles reconnaissent-elles un micro-organisme ?', 'mcq', '["Par des récepteurs détectant des motifs moléculaires communs à des familles entières","Par un récepteur unique propre à chaque agent","Par la mémoire d’une rencontre antérieure","Par les anticorps qu’elles produisent"]'::jsonb, 0, 'C’est ce qui rend la réponse non spécifique.', 6),
    ('84aac80e-b014-5b85-b9af-30044b3c1520'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Les médiateurs de l’inflammation provoquent une vasodilatation locale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où la rougeur, la chaleur et l’afflux de cellules immunitaires.', 7),
    ('d08eaaad-c4ad-502b-85ca-984b21947496'::uuid, '2dc4e316-9a61-59f4-b3be-c84640df3c6e'::uuid, 'Les anti-inflammatoires suppriment une réponse toujours nuisible à l’organisme.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’inflammation est une défense utile : la réduire n’est justifié que si elle est excessive.', 8),
    ('4e18ab19-a486-531b-800b-da995e5c7284'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Quelles cellules produisent les anticorps ?', 'mcq', '["Les plasmocytes, issus des lymphocytes B","Les lymphocytes T cytotoxiques","Les macrophages","Les cellules dendritiques"]'::jsonb, 0, 'Ils sont la forme différenciée et sécrétrice du lymphocyte B.', 1),
    ('e0c62b0c-2776-5119-b4b0-2bf5f6d74141'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Un anticorps peut pénétrer dans une cellule pour y détruire un virus.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il agit dans les liquides ; contre un agent intracellulaire, c’est le LT8 qui intervient.', 2),
    ('3afbeb20-daf4-5105-a872-1a893aae80f0'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Quelle cellule coordonne l’ensemble de la réponse adaptative ?', 'mcq', '["Le lymphocyte T auxiliaire (LT4)","Le lymphocyte B","Le macrophage","Le plasmocyte"]'::jsonb, 0, 'Ses interleukines amplifient les réponses humorale et cellulaire.', 3),
    ('21b7689e-6e80-54f0-8dab-12db2d429078'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Qu’est-ce que la sélection clonale ?', 'mcq', '["L’antigène sélectionne et amplifie le clone de lymphocytes qui le reconnaît déjà","L’antigène crée un récepteur adapté","Les lymphocytes se clonent au hasard","Les cellules infectées sont clonées"]'::jsonb, 0, 'Le répertoire préexiste à toute rencontre avec l’antigène.', 4),
    ('91e6a065-aada-514b-9ab7-d1d81e620a9a'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Quel type de lymphocyte détruit les cellules infectées par un virus ?', 'mcq', '["Le lymphocyte T cytotoxique (LT8)","Le lymphocyte B","Le plasmocyte","Le lymphocyte T auxiliaire"]'::jsonb, 0, 'C’est la réponse cellulaire, seule efficace contre un agent intracellulaire.', 5),
    ('7ece84a4-0336-5e19-9b7c-f1e2010d7e76'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Pourquoi le VIH désorganise-t-il toute la réponse immunitaire ?', 'mcq', '["Parce qu’il détruit les lymphocytes T auxiliaires","Parce qu’il détruit les globules rouges","Parce qu’il empêche la phagocytose","Parce qu’il bloque la moelle osseuse"]'::jsonb, 0, 'Le chef d’orchestre disparaissant, les deux voies s’effondrent.', 6),
    ('6f6c2d42-1620-5cc0-8b32-fc17624effa8'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'La réponse adaptative secondaire est plus rapide et plus intense que la première.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Grâce aux lymphocytes mémoire : c’est le principe même de la vaccination.', 7),
    ('bc8a93f6-d7b9-57b7-ac8d-eab33bf54029'::uuid, 'fe357455-dcef-53ab-a05c-54c56877e8ca'::uuid, 'Qu’est-ce qu’un complexe immun ?', 'mcq', '["L’association d’un anticorps et de son antigène","Un groupe de lymphocytes mémoire","Un organe lymphoïde","Un récepteur membranaire"]'::jsonb, 0, 'Il est ensuite éliminé par phagocytose.', 8),
    ('47be7fd1-8ef9-5e3f-ac54-81da84d470b8'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Sur quoi repose l’efficacité de la vaccination ?', 'mcq', '["La constitution d’une mémoire immunitaire","L’injection d’anticorps déjà formés","La destruction directe de l’agent infectieux","Le renforcement de la barrière cutanée"]'::jsonb, 0, 'La réponse secondaire, plus rapide et plus intense, stoppe l’infection précocement.', 1),
    ('df1e39ef-4fee-57fc-8ef6-e40f755136d3'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'La sérothérapie confère une protection durable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est immédiate mais brève et sans mémoire : les anticorps injectés se dégradent.', 2),
    ('00cb1196-cd31-5aad-acb2-18d09fa93a9a'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'À quoi sert un adjuvant dans un vaccin ?', 'mcq', '["À stimuler l’immunité innée pour déclencher une bonne réponse adaptative","À conserver le vaccin plus longtemps","À neutraliser l’agent infectieux","À réduire la douleur de l’injection"]'::jsonb, 0, 'Sans réponse innée suffisante, l’immunité adaptative se met mal en place.', 3),
    ('cb31fda2-165b-5dd2-9660-c67cc4e9e189'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Qu’est-ce que l’immunité collective ?', 'mcq', '["La protection des non-vaccinés par un taux de couverture vaccinale élevé","L’immunité acquise par un groupe après une épidémie uniquement","La vaccination obligatoire","La mémoire immunitaire d’un individu"]'::jsonb, 0, 'Au-delà d’un certain seuil, la chaîne de transmission se rompt.', 4),
    ('c2e4735d-1058-5499-9ab8-a201ee9524a3'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Pourquoi le rappel vaccinal est-il utile ?', 'mcq', '["Il sollicite les lymphocytes mémoire et renforce durablement la protection","Il remplace le vaccin initial devenu inefficace","Il apporte de nouveaux anticorps","Il élimine les effets secondaires"]'::jsonb, 0, 'La réponse secondaire est plus intense et plus durable.', 5),
    ('afd035a5-305d-5c8d-b2c3-c4e3eb5a0f33'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Un vaccin à ARN messager fournit à l’organisme les instructions pour fabriquer lui-même l’antigène.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La cellule traduit l’ARN, présente l’antigène, et la réponse adaptative se déclenche.', 6),
    ('b3f0f957-daa0-569a-a8af-51aea19b1e7a'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Que font les inhibiteurs de points de contrôle en immunothérapie ?', 'mcq', '["Ils lèvent le frein exercé par la tumeur sur les lymphocytes T","Ils tuent directement les cellules tumorales","Ils empêchent l’angiogenèse","Ils réparent l’ADN muté"]'::jsonb, 0, 'Le système immunitaire du patient redevient capable d’attaquer la tumeur.', 7),
    ('ecca69c9-9703-5a16-9897-9b867e192633'::uuid, 'fe79b6ca-8fd8-5581-9624-8e6b8796d8ef'::uuid, 'Quelle stratégie convient à une urgence, chez une personne non vaccinée exposée au tétanos ?', 'mcq', '["La sérothérapie","La vaccination seule","Un traitement antibiotique préventif","Une immunothérapie CAR-T"]'::jsonb, 0, 'Seuls des anticorps déjà formés agissent immédiatement.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('svt');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('svt')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 269 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 269 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
